def arxiv_search_expression(query: str) -> str:
    terms = [x for x in re.findall(r"[A-Za-z0-9._+-]+", query) if x.lower() not in ARXIV_STOPWORDS]
    anchors = terms[:min(3, len(terms))]
    if not anchors:
        anchors = [clean_text(query)]
    return " AND ".join(f"all:{json.dumps(x)}" for x in anchors)
